const resp = $input.first().json;
const projects = (resp && resp.data && resp.data.projects && resp.data.projects.nodes) || [];
const graphqlErrors = (resp && resp.errors) || null;

const out = [];

for (const project of projects) {
  const links = (project.externalLinks && project.externalLinks.nodes) || [];
  const codeLink = links.find(l => l.label === 'Code');
  if (!codeLink || !codeLink.url) continue;

  const match = codeLink.url.match(/github\.com[\/:]([^\/]+)\/([^\/\.\?#]+)/);
  if (!match) continue;
  const repoOwner = match[1];
  const repoName = match[2].replace(/\.git$/, '');

  const issues = (project.issues && project.issues.nodes) || [];
  for (const issue of issues) {
    const labelNames = ((issue.labels && issue.labels.nodes) || []).map(l => l.name);
    if (labelNames.includes('AI Plan')) continue;
    if (labelNames.includes('AI Skip CI')) continue;

    out.push({
      issueId: issue.id,
      issueIdentifier: issue.identifier,
      issueTitle: issue.title,
      issueUrl: issue.url,
      projectName: project.name,
      repoOwner,
      repoName,
      repoUrl: codeLink.url,
      labels: labelNames,
      triggeredAt: new Date().toISOString()
    });
  }
}

if (out.length === 0) {
  return [{ json: { candidates: [], graphqlErrors } }];
}
return [{ json: { candidates: out, graphqlErrors } }];

const resp = $input.first().json;
const projects = (resp && resp.data && resp.data.projects && resp.data.projects.nodes) || [];
const graphqlErrors = (resp && resp.errors) || null;

const out = [];

for (const project of projects) {
  const links = (project.externalLinks && project.externalLinks.nodes) || [];
  const codeLink = links.find(l => l.label === 'Code');
  if (!codeLink || !codeLink.url) continue;

  const match = codeLink.url.match(/github\.com[\/:]([^\/]+)\/([^\/\.\?#]+)/);
  if (!match) continue;
  const repoOwner = match[1];
  const repoName = match[2].replace(/\.git$/, '');

  const issues = (project.issues && project.issues.nodes) || [];
  for (const issue of issues) {
    const labelNames = ((issue.labels && issue.labels.nodes) || []).map(l => l.name);
    if (!labelNames.includes('AI Plan')) continue;
    if (labelNames.includes('AI Skip CI')) continue;

    const attachments = (issue.attachments && issue.attachments.nodes) || [];
    const planAttachment = attachments.find(a => /plan\.md/i.test(a.title || '') || /plan\.md/i.test(a.url || ''));

    out.push({
      issueId: issue.id,
      issueIdentifier: issue.identifier,
      issueTitle: issue.title,
      issueDescription: issue.description || '',
      issueUrl: issue.url,
      teamId: (issue.team && issue.team.id) || null,
      projectName: project.name,
      repoOwner,
      repoName,
      repoUrl: codeLink.url,
      planAttachmentUrl: planAttachment ? planAttachment.url : null,
      hasPlan: !!planAttachment,
      labels: labelNames,
      branchName: issue.identifier.toLowerCase(),
      triggeredAt: new Date().toISOString()
    });
  }
}

if (out.length === 0) {
  return [{ json: { candidates: [], graphqlErrors } }];
}
return [{ json: { candidates: out, graphqlErrors } }];
